    six = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not four or not six:
        return out

    for r, c in six:
        out[r][c] = 0
    r0, r1 = min(r for r, c in four), max(r for r, c in four)
    c0, c1 = min(c for r, c in four), max(c for r, c in four)
    sr0, sr1 = min(r for r, c in six), max(r for r, c in six)
    sc0, sc1 = min(c for r, c in six), max(c for r, c in six)
    row_counts = [sum(1 for r, c in six if r == rr) for rr in range(sr0, sr1 + 1)]
    col_counts = [sum(1 for r, c in six if c == cc) for cc in range(sc0, sc1 + 1)]

    # A T-shaped marker selects horizontal reflection: its broad end gives
    # the direction (broad top -> right; broad bottom -> left).
    if len(row_counts) >= 3 and max(row_counts) > max(col_counts):
